import{_ as i,o as a,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2022-01-20","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-01-20","date":"2022-01-20T00:00:00.000Z","updated":"2022-01-21T00:00:00.000Z","tags":["Ceph","性能测试","Quincy 版本","存储优化","故障恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-01-20.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-01-20.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-01-20.md"};function o(n,e,s,c,u,h){return a(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Ceph Quincy 版本准备</strong>：团队正在为 Quincy 版本的发布做准备，重点关注任务完成和 bug 修复。</li><li><strong>已合并的修复</strong>： <ul><li>解决了 RGW 的 bucket loading 统计问题。</li><li>优化了 shared blob fsck 的内存使用。</li></ul></li><li><strong>PR 更新</strong>： <ul><li>简化了 pinning logic 和 blue store cache 的 PR 更新。</li><li>修复了 FreeBSD 的 huge page based read buffers 问题，等待测试反馈。</li><li>优化了 PG 移除的 PR 更新。</li></ul></li><li><strong>性能测试</strong>： <ul><li>正在进行 Quincy 版本的性能测试，主要针对 Pacific 版本。</li><li>决定跳过 iSCSI 测试，因为其重要性不高。</li><li>讨论了是否继续在大规模测试中收集性能指标，初步决定可能禁用部分测试的性能指标收集。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>性能测试策略</strong>：讨论了是否在大规模测试中继续收集性能指标，以及如何进行恢复测试。</li><li><strong>iSCSI 测试的重要性</strong>：决定暂时跳过 iSCSI 测试，因为其对当前版本的影响不大。</li><li><strong>恢复测试方法</strong>：计划使用 fio 进行恢复测试，观察集群在 OSD 故障和恢复后的行为。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>跳过 iSCSI 测试。</li><li>可能在大规模测试中禁用部分性能指标的收集。</li><li>使用 fio 进行恢复测试，观察集群在 OSD 故障和恢复后的行为。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li>继续进行 Quincy 版本的性能测试，重点关注 Pacific 版本的测试结果。</li><li>完成 fio 恢复测试，观察集群在不同负载下的恢复行为。</li><li>如果有任何性能测试需要核心团队参与，应及时通知并讨论。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>提到了正在进行的大规模测试，使用了一个包含 975 个 OSD 的集群，以覆盖更多的测试场景。</li><li>鼓励团队成员如果有任何测试需求或问题，及时与核心团队沟通。</li></ul>',11)])])}const g=i(r,[["render",o]]);export{_ as __pageData,g as default};
